def product_page(p,lang='fr'):
 T=lambda f,a:trans(f,a,lang);ar=lang=='ar';prefix='../../' if ar else '../';folder='ar/produits/' if ar else 'produits/';path=folder+p['slug']+'.html';home=prefix+('ar.html' if ar else 'index.html');cat=p.get('catAr',p['cat']) if ar else p['cat']
 title=f'{p["name"]} | {p["sub"]} — BIOJOUD Maroc'
 out=head(title,p['desc'],path,lang,p)+header(lang,prefix,True,p['slug'])
